type StorageModuleConfig struct {
	// MountPoint, if set, prefixes both UploadsBasePath and
	// DownloadsBasePath, e.g. MountPoint "/api" with the default base paths
	// mounts "/api/files" and "/api/downloads". Slashes are normalized, so
	// it doesn't matter whether MountPoint/UploadsBasePath/DownloadsBasePath
	// have leading/trailing slashes or not - the joined result never has
	// missing or doubled-up slashes.
	MountPoint string

	// UploadsBasePath is where the tus protocol endpoints
	// (POST/HEAD/PATCH/GET/DELETE, see handler.go's Mount) are mounted.
	// Defaults to "/files".
	UploadsBasePath string

	// DownloadsBasePath is where the JSON metadata + range-capable download
	// endpoints (see download.go's MountDownloads) are mounted. Defaults to
	// "/downloads".
	DownloadsBasePath string

	// ReaperInterval is how often SweepOrphaned runs in the background to
	// delete uploads nothing has claimed. Defaults to 1 hour. A negative
	// value disables the reaper entirely.
	ReaperInterval time.Duration

	// UnclaimedTTL/IncompleteTTL feed SweepOrphaned - see its docs in
	// reaper.go. Both default to 24h.
	UnclaimedTTL  time.Duration
	IncompleteTTL time.Duration

	// DisableUploadsMount, if true, skips mounting the tus upload endpoints
	// (Mount: POST/HEAD/PATCH/GET/DELETE at UploadsBasePath) entirely.
	// Useful for a deployment that only ever writes uploads out-of-band (via
	// Admin.UploadFile / the CLI, see Cli.go) and wants no public write
	// endpoint at all. The reaper and download endpoints are unaffected.
	DisableUploadsMount bool

	// DisableDownloadsMount, if true, skips mounting the read-only download
	// endpoints (MountDownloads: JSON metadata + ranged /raw at
	// DownloadsBasePath) entirely. Useful when an app wants to serve files
	// through its own signed-URL/proxy/CDN layer instead of exposing this
	// module's download routes directly.
	DisableDownloadsMount bool

	// Authenticate resolves an incoming request's identity - typically by
	// reading its Authorization header - into an AuthContext. It's the
	// single place fileupload looks up who's making a request: Mount and
	// MountDownloads both call it on every request, and its result is what
	// gets persisted per upload (see AuthContext, FileRecord) and passed to
	// Quota.
	//
	// Leave nil to disable authentication entirely: every request is
	// treated as Anonymous - no owner is recorded, Quota is never
	// consulted, and every upload is readable/writable by anyone. That's
	// this module's behavior from before this mechanism existed.
	//
	// Inside a fireback app, StorageModuleSetup defaults this to
	// resolving the same bearer token fireback's own
	// SecurityModel/WithAuthorization middleware resolves elsewhere in the
	// app (via fireback.WithAuthorizationPure) - see defaultAuthenticate in
	// webserver.go. Set your own to customize, e.g. to also require a
	// specific permission, or to plug in an entirely different auth scheme.
	Authenticate func(c *gin.Context) (AuthContext, error)

	// Quota returns the maximum total bytes auth is allowed to have stored
	// across all of their uploads combined. It's checked once per upload
	// creation, against the size the client declares up front (its
	// Upload-Length header) plus whatever auth already has stored -
	// uploads that would cross the limit are rejected before a single byte
	// is written.
	//
	// Defaults to a flat DefaultQuotaBytes (2 GiB) per user if nil. Return
	// a negative number for "no limit" for a given identity, e.g. based on
	// AccessLevel - this is the extension point for per-user/per-plan
	// quotas. Never consulted for Anonymous auth (Authenticate is nil, or
	// it resolved no UserId).
	Quota func(auth AuthContext) int64
}

